test('🔖 semver: validação e precedência (semver.org §11)', () => {
  for (const v of ['1.0.0', '0.1.0', '1.0.0-rc.1', '1.0.0+build.5', '10.20.30-alpha.beta']) assert.ok(semver.valid(v), v);
  for (const v of ['1.0', '01.0.0', '1.0.0-', '1.0.0-01', 'a.b.c']) assert.ok(!semver.valid(v), v);
  const order = ['1.0.0-alpha', '1.0.0-alpha.1', '1.0.0-alpha.beta', '1.0.0-beta', '1.0.0-beta.2', '1.0.0-beta.11', '1.0.0-rc.1', '1.0.0'];
  for (let i = 1; i < order.length; i++) assert.equal(semver.compare(order[i - 1], order[i]), -1, `${order[i - 1]} < ${order[i]}`);
  assert.equal(semver.bumpType('1.2.3', '2.0.0'), 'major');
  assert.equal(semver.bumpType('1.2.3', '1.3.0'), 'minor');
  assert.equal(semver.bumpType('1.2.3', '1.2.4'), 'patch');
  assert.equal(semver.requiredBump('major', '0.4.0'), 'minor');
  assert.equal(semver.maxBump(['patch', null, 'minor']), 'minor');
});

test('😜 gitmoji: formato da especificação', () => {
  for (const ok of ['✨ Add login page', '⚡️ Lazyload home screen images.', '♻️ (components): Transform classes to hooks',
    ':bug: Fix header overlap', '🐛 (header) Fix overlap', '🧑‍💻 Improve local setup', '⚡ Speed up build', '🔖 Release v1.2.0'])
    assert.deepEqual(gitmoji.validate(ok).errors, [], ok);
  for (const bad of ['feat: add login', 'Add login', '✨add login', '🙂 Add smile', '✨', `✨ ${'x'.repeat(120)}`])
    assert.ok(gitmoji.validate(bad).errors.length, bad);
  assert.equal(gitmoji.parseHeader('♻️ (auth): Extract service').scope, 'auth');
  assert.equal(gitmoji.parseHeader(':boom: Drop Node 18').gitmoji.semver, 'major');
  assert.ok(gitmoji.validate('fixup! ✨ Add x', { pr: true }).skipped);
  assert.ok(gitmoji.validate("Merge branch 'main' into feature/x", { pr: true }).skipped);
  assert.ok(gitmoji.validate("Merge branch 'main' into feature/x").errors.length);
});

test('🙅 gitmoji: nenhuma atribuição de IA', () => {
  const msgs = [
    '✨ Add login\n\nCo-Authored-By: Claude <noreply@anthropic.com>',
    '✨ Add login\n\n🤖 Generated with [Claude Code](https://claude.com/claude-code)',
    '✨ Add login\n\nCo-authored-by: Copilot <175728472+Copilot@users.noreply.github.com>',
    '♻️ Refactor auth (feito com IA)',
    '🐛 Fix bug generated by ChatGPT',
  ];
  for (const m of msgs) assert.ok(gitmoji.validate(m).errors.some((e) => e.includes('IA')), m);
  for (const ok of ['✨ Add AI search to catalog', '✨ (ia): Add recommendation model', '👽️ Update OpenAI client to v5', '🐛 Fix cursor pagination'])
    assert.deepEqual(gitmoji.validate(ok).errors, [], ok);
  const cleaned = gitmoji.stripAiTrailers(msgs[0] + '\n');
  assert.equal(cleaned, '✨ Add login\n');
  assert.equal(gitmoji.stripAiTrailers(msgs[1]), '✨ Add login\n');
});

test('🌳 branch: fixtures oficiais da Conventional Branch (sem prefixos de IA e com nossas trunks)', () => {
  const { cases } = JSON.parse(fs.readFileSync(path.join(__dirname, 'conventional-branch.fixtures.json'), 'utf8'));
  for (const c of cases) {
    const prefix = c.branch.split('/')[0];
    let expected = c.valid;
    if (['master', 'develop'].includes(c.branch)) expected = false;          // trunks daqui: main, test, sandbox
    if (branch.AI_PREFIXES.includes(prefix) && c.branch.includes('/')) expected = false; // IA nunca no nome
    assert.equal(branch.validate(c.branch).ok, expected, `${c.branch} (${c.reason})`);
    assert.equal(new RegExp(branch.REGEX).test(c.branch), expected, `regex: ${c.branch}`);
  }
  for (const ok of ['main', 'test', 'sandbox', 'feat/issue-123-login', 'release/v1.2.0', 'release/v2.0.0-rc.1', 'dependabot/npm_and_yarn/next-15.0.1'])
    assert.ok(branch.validate(ok).ok, ok);
  for (const bad of ['claude/fix-x', 'ai/refactor', 'copilot/add', 'release/1.2.0', 'release/next', 'Feature/x', 'feature/x--y', 'wip/x'])
    assert.ok(!branch.validate(bad).ok, bad);
  assert.match(branch.validate('claude/fix-x').errors[0], /IA/);
});

test('🎯 branch: destinos permitidos', () => {
  assert.equal(branch.allowedTarget('feature/x', 'main', false), true);
  assert.equal(typeof branch.allowedTarget('feature/x', 'main', true), 'string');
  assert.equal(branch.allowedTarget('release/v1.0.0', 'main', true), true);
  assert.equal(branch.allowedTarget('hotfix/x', 'main', true), true);
  assert.equal(branch.allowedTarget('main', 'test', true), true);
  assert.equal(typeof branch.allowedTarget('release/v1.0.0', 'test', true), 'string');
  assert.equal(branch.allowedTarget('fix/x', 'sandbox', true), true);
});

const CL = `# Changelog

## [1.1.0] - 2026-11-25

### Changed

- **Breaking:** require Node.js 20 ([\`a1b2c3d\`](https://github.com/o/r/commit/a1b2c3d))

### Added

- Add login page ([#12](https://github.com/o/r/pull/12)) (Gabriel)

### Fixed

- Fix header overlap ([#14](https://github.com/o/r/pull/14))

## [1.0.0] - 2026-10-01

_Initial release._

[1.1.0]: https://github.com/o/r/releases/tag/v1.1.0
[1.0.0]: https://github.com/o/r/releases/tag/v1.0.0
`;

test('📝 changelog: Common Changelog', () => {
  assert.deepEqual(changelog.validate(CL, '1.1.0'), []);
  assert.ok(changelog.validate(CL, '1.2.0').length);
  assert.ok(changelog.validate(CL.replace('### Fixed', '### Security')).length);
  assert.ok(changelog.validate(CL.replace('### Added', '### Fixedx')).length);
  assert.ok(changelog.validate(CL.replace(/### Fixed[\s\S]*?## \[1\.0\.0\]/, '### Fixed\n\n## [1.0.0]').replace('### Changed', '### Fixed').replace('### Added', '### Added')).length, 'fora de ordem');
  assert.ok(changelog.validate(CL.replace('(Gabriel)', '').replace(' ([#12](https://github.com/o/r/pull/12))', '')).length, 'sem referência');
  assert.ok(changelog.validate(CL.replace('# Changelog', '# Changelog\n\n## [Unreleased]')).length);
  assert.ok(changelog.validate(CL.replace('[1.1.0]: https://github.com/o/r/releases/tag/v1.1.0\n', '')).length, 'sem link');
  assert.match(changelog.section(CL, '1.1.0'), /^### Changed/);
});

