const language = require('../lib/language');
const standards = require('../lib/standards');
const { changedOnly } = require('../projects');
const L = (arr) => arr.map((text, i) => ({ n: i + 1, text }));

test('💻 idioma: identificadores em inglês, comentários e strings livres', () => {
  const hits = (file, code, terms) => [...new Set(language.checkLines(file, L(code.split('\n')), terms).map((h) => h.identifier))];
  assert.deepEqual(hits('a.ts', 'const totalPagamentos = calcularTaxa(valorBruto);'), ['totalPagamentos', 'calcularTaxa', 'valorBruto']);
  assert.deepEqual(hits('a.ts', 'const paymentTotal = calculateFee(grossAmount); // calcula a taxa do cliente\nconst msg = "Olá, usuário";'), []);
  assert.deepEqual(hits('a.py', 'def criar_usuario(nome):\n    """Cria o usuário com nome."""\n    return User(name=nome)'), ['criar_usuario', 'nome']);
  assert.deepEqual(hits('a.py', 'class Payment(Base):\n    __tablename__ = "pagamentos"\n    amount = Column("valor", Numeric)'), ['pagamentos', 'valor']);
  assert.deepEqual(hits('schema.prisma', 'model Payment {\n  amount Decimal @map("valor_bruto")\n  @@map("pagamentos")\n}'), ['valor_bruto', 'pagamentos']);
  assert.deepEqual(hits('m.sql', 'CREATE TABLE "clientes" (nome text); -- tabela de clientes'), ['clientes', 'nome']);
  assert.deepEqual(hits('a.dart', 'final preçoFinal = 10;'), ['preçoFinal']);
  assert.deepEqual(hits('a.ts', 'const pixKey = boletoBarcode + cnpj;', ['pix', 'boleto', 'cnpj']), []);
  assert.deepEqual(hits('a.ts', 'removeLabel(); const status = data.total; const agenda = terminalId;'), []);
  assert.deepEqual(hits('a.sh', 'cat <<EOF\nnão é código, é texto do usuário\nEOF\nREPO=$1'), []);
  assert.deepEqual(hits('README.md', 'const valor = 1'), []); // markdown não é código
});

test('🤖 idioma: arquivos para IA em inglês', () => {
  assert.equal(language.portugueseRatio('Code must be in English. Never commit secrets. Run tests before done.').portuguese, false);
  assert.equal(language.portugueseRatio('O código deve estar sempre em inglês e você nunca deve usar acentos. Também não faça commit de segredos, isso é para a segurança do projeto quando for para produção com mais de um time.').portuguese, true);
  assert.equal(language.portugueseRatio('Use `não` in strings only:\n```\nconst msg = "não é para isso que serve"\n```\nKeep code English.').portuguese, false);
});

test('☁️ políticas: hospedagem × criticidade, IaC, ORM e idiomas', () => {
  const base = standards.load('/nonexistent');
  const pol = (patch) => {
    const c = JSON.parse(JSON.stringify(base));
    for (const [k, v] of Object.entries(patch)) Object.assign(c[k], v);
    return standards.policy(c, '/nonexistent');
  };
  assert.deepEqual(pol({}).errors, []);
  assert.ok(pol({ infra: { hosting: 'vps', criticality: 'medium' } }).errors.some((e) => e.includes('VPS')));
  assert.deepEqual(pol({ infra: { hosting: 'vps', criticality: 'low' } }).errors, []);
  assert.ok(pol({ infra: { hosting: 'vps', criticality: 'low', pciScope: true } }).errors.some((e) => e.includes('PCI')));
  assert.ok(pol({ infra: { hosting: 'gcp' } }).errors.some((e) => e.includes('ADR')));
  assert.ok(pol({ infra: { hosting: 'azure', iac: 'cdk' } }).errors.some((e) => e.includes('terraform')));
  assert.deepEqual(pol({ infra: { hosting: 'aws', iac: 'cdk' } }).errors, []);
  assert.ok(pol({ database: { engine: 'postgresql' } }).errors.some((e) => e.includes('ORM')));
  assert.deepEqual(pol({ database: { engine: 'postgresql', orm: 'prisma' } }).errors, []);
  assert.ok(pol({ docs: { languages: ['en', 'pt-BR'] } }).errors.some((e) => e.includes('README.pt-BR.md')));
  assert.ok(pol({ code: { language: 'pt-BR' } }).errors.length);
  assert.ok(standards.matchAny('apps/web/src/generated/api.ts', ['**/generated/**']));
  assert.ok(standards.matchAny('.claude/settings.json', ['.claude/**']));
  assert.ok(standards.matchAny('skills/x/SKILL.md', ['**/SKILL.md']) && standards.matchAny('SKILL.md', ['**/SKILL.md']));
});

test('⏱️ CI: só projetos afetados', () => {
  const list = [{ dir: '.', stack: 'node' }, { dir: 'services/api', stack: 'python' }, { dir: 'mobile/app', stack: 'flutter' }];
  const dirs = (changed) => changedOnly(list, changed).map((p) => p.dir);
  assert.deepEqual(dirs(['services/api/app/main.py']), ['services/api']);
  assert.deepEqual(dirs(['README.md', 'docs/x.md', 'services/api/README.md']), []);
  assert.deepEqual(dirs(['src/index.ts']), ['.']);
  assert.deepEqual(dirs(['.github/workflows/ci.yml']), ['.', 'services/api', 'mobile/app']);
  assert.deepEqual(dirs(['pnpm-lock.yaml']), ['.', 'services/api', 'mobile/app']);
});

test('📦 standards: módulos opcionais', () => {
  const fs2 = require('fs'), os = require('os'), p = require('path');
  const tmp = fs2.mkdtempSync(p.join(os.tmpdir(), 'mods-'));
  fs2.mkdirSync(p.join(tmp, '.github'));
  assert.deepEqual(standards.load(tmp).modules, []);
  assert.deepEqual(standards.DEFAULTS.modules, [], 'default não é mutado');
  fs2.writeFileSync(p.join(tmp, '.github/standards.json'), JSON.stringify({ modules: ['github', 'nextjs'] }));
  const cfg = standards.load(tmp);
  assert.ok(Array.isArray(cfg.modules), 'lista continua lista (não vira objeto)');
  assert.deepEqual(cfg.modules, ['github', 'nextjs']);
  assert.deepEqual(standards.policy(cfg, tmp).errors, []);
  assert.ok(standards.policy({ ...cfg, modules: ['github', 'kubernetes'] }, tmp).errors.some((e) => e.includes('kubernetes')));
  assert.ok(standards.policy({ ...cfg, modules: 'github' }, tmp).errors.some((e) => e.includes('lista')));
  assert.equal(new Set(standards.KNOWN_MODULES).size, 13);
});

test('📊 cobertura: Clover (PHPUnit/Pest)', () => {
  const { clover, parse } = require('../coverage');
  const xml = `<?xml version="1.0" encoding="UTF-8"?>
<coverage generated="1"><project timestamp="1">
  <file name="/app/src/Fee.php"><class name="Fee"><metrics complexity="1" methods="1" coveredmethods="1" conditionals="0" coveredconditionals="0" statements="4" coveredstatements="3" elements="5" coveredelements="4"/></class>
    <line num="5" type="stmt" count="1"/><metrics loc="20" ncloc="15" classes="1" methods="1" coveredmethods="1" conditionals="2" coveredconditionals="1" statements="4" coveredstatements="3" elements="5" coveredelements="4"/></file>
  <file name="/app/src/Refund.php"><metrics loc="10" ncloc="8" classes="1" methods="1" coveredmethods="0" conditionals="0" coveredconditionals="0" statements="6" coveredstatements="5" elements="7" coveredelements="5"/></file>
  <metrics files="2" loc="30" ncloc="23" classes="2" methods="2" coveredmethods="1" conditionals="2" coveredconditionals="1" statements="10" coveredstatements="8" elements="12" coveredelements="9"/>
</project></coverage>`;
  const c = clover(xml);
  assert.equal(c.lines, 80);
  assert.equal(c.branches, 50);
  assert.equal(c.lf, 10);
  assert.equal(parse(xml).lines, 80, 'parse detecta Clover');
  const noProject = xml.replace(/<metrics files="2"[^>]*\/>/, '');
  assert.equal(clover(noProject).lines, 80, 'sem métricas de projeto soma as de arquivo');
  assert.equal(parse('SF:a\nLF:4\nLH:3\nend_of_record\n').lines, 75, 'lcov continua igual');
});

test('🐘 CI: projetos PHP (composer.json)', () => {
  const fs2 = require('fs'), os = require('os'), p = require('path');
  const { detect } = require('../projects');
  const tmp = fs2.mkdtempSync(p.join(os.tmpdir(), 'php-'));
  fs2.mkdirSync(p.join(tmp, 'apps/legacy/vendor/acme'), { recursive: true });
  fs2.writeFileSync(p.join(tmp, 'apps/legacy/composer.json'), '{}');
  fs2.writeFileSync(p.join(tmp, 'apps/legacy/vendor/acme/composer.json'), '{}');
  assert.deepEqual(detect(tmp), [{ dir: 'apps/legacy', stack: 'php' }], 'vendor/ ignorado');
});
